/*
 * A246361  Numbers n such that if 2n-1 = product_{k >= 1} (p_k)^(c_k), then n
 *          >= product_{k >= 1} (p_{k-1})^(c_k), where p_k indicates the k-th
 *          prime, A000040(k).
 * https://oeis.org/A246361
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n‑th integer such that for 2*n-1 = ∏ p_k^{c_k}, * we
 *            have n ≥ ∏ p_{k-1}^{c_k} (with p_0 interpreted as 1). * The
 *            sequence is generated by testing successive integers and caching
 *            * the results
 * Range:     u8 n <= 76, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   factor_u64, prev_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/factor_u64.h"
#include "../utils/prev_prime.h"

/* Cache for the sequence values. */
static seq_t *seq = NULL;
static size_t seq_len = 0;
static size_t seq_cap = 0;
static uint64_t last_checked = 0;

/* Append a term to the cache, resizing if necessary. */
static void append_term(seq_t val)
{
    if (seq_len == seq_cap) {
        size_t new_cap = seq_cap == 0 ? 16 : seq_cap * 2;
        seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
        if (!tmp) abort();
        seq = tmp;
        seq_cap = new_cap;
    }
    seq[seq_len++] = val;
}

/* Test whether a candidate satisfies the defining inequality. */
static bool satisfies_candidate(uint64_t c)
{
    uint64_t m = 2 * c - 1;                /* 2*n-1 */
    uint64_t pf[32], ex[32];
    size_t cnt = 0;
    factor_u64(m, pf, ex, &cnt);          /* factorization of m */

    __uint128_t prod = 1;                  /* use 128‑bit to avoid overflow */
    for (size_t i = 0; i < cnt; ++i) {
        uint64_t p = pf[i];
        unsigned int e = (unsigned int)ex[i];
        uint64_t prev = (p == 2) ? 1 : prev_prime(p);

        for (unsigned int k = 0; k < e; ++k) {
            prod *= prev;
            if (prod > c) return false;   /* early exit if product already larger */
        }
    }
    return prod <= c;
}

/* Return the n-th term of A246361 (1‑based indexing). */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                 /* undefined, but safe */

    while (seq_len < n) {                 /* generate terms as needed */
        ++last_checked;
        if (satisfies_candidate(last_checked))
            append_term((seq_t)last_checked);
    }
    return seq[n - 1];
}
